std::shared_mutex state_lock;
int data_count = 0;

void concurrent_read() {
    // Shared lock: Allows other readers, blocks writers
    std::shared_lock<std::shared_mutex> lk(state_lock);
    // Reads protected resource
    int local_copy = data_count;
} // shared lock released

void exclusive_write(int new_val) {
    // Unique lock: Blocks all other access (readers/writers)
    std::unique_lock<std::shared_mutex> lk(state_lock);
    // Writes protected resource
    data_count = new_val;
} // unique lock released
